function updateDebrisVisuals(now:number){for(const f of allDebris(flight!)){let group=debrisVisuals.get(f);if(!group){group=new T.Group();for(const p of f.parts){const o=makePartVisual(p);if(PARTS[p.type].thrust&&!PARTS[p.type].water){const flame=createEnginePlume(PARTS[p.type],!!o.userData.gimbal);const target=o.userData.gimbal||o;target.add(flame);o.userData.debrisFlame=flame;}group.add(o);}testWorld.add(group);debrisVisuals.set(f,group);group.userData.canopies=new Map();for(const p of f.parts)if(PARTS[p.type].parachute){const canopy=cloneModel('parachute-open');testWorld.add(canopy);group.userData.canopies.set(p.id,canopy);}}for(const [id,canopy]of group.userData.canopies){const state=f.chutes.get(id),p=f.parts.find(p=>p.id===id);canopy.visible=!!p&&!!state&&state.fraction>0;if(canopy.visible){canopy.position.fromArray(p!.p).applyQuaternion(f.q).add(f.pos);canopy.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),bodyUp(canopy.position,f.universalTime));const scale=Math.sqrt(state!.fraction);canopy.scale.set(scale,.45+.55*scale,scale);}}syncEngineShrouds(f.parts,new Map(group.children.map(o=>[o.userData.partId,o])),assets.get('engine-shroud'));group.position.copy(f.pos);group.quaternion.copy(f.q);for(const o of group.children){const id=o.userData.partId;o.visible=f.parts.some(p=>p.id===id);markWreckVisual(o,f);updateRCSVisual(o,f);const cp=f.parts.find(p=>p.id===id);if(cp)syncCargoVisual(o,cp,PARTS[cp.type]);if(o.userData.debrisFlame){updateEnginePlume(o.userData.debrisFlame,f.engineThrust.get(id)||0,f.crashed,now);}if(o.userData.hinge)o.userData.hinge.rotation.x=f.deflections.get(id)||0;if(o.userData.gimbal){const g=f.gimbals.get(id);o.userData.gimbal.rotation.set(g?.x||0,0,g?.z||0);}if(o.userData.rollingVisual){const wheel=f.wheelMotion.get(id);o.userData.steeringVisual.position.y=-(wheel?.extension??0);o.userData.steeringVisual.rotation.y=wheel?.steer||0;o.userData.rollingVisual.rotation.x=wheel?.angle||0;}}}}
function updateDebrisList(){const notice=$('#trackingFocus');notice.hidden=!trackedDebris;if(trackedDebris){$('#trackingName').textContent='追跡：'+(trackedDebris.vesselName||'分離機');$('#trackingName').title=trackedDebris.vesselName||'分離機';$('#trackingControl').textContent='操作・計器：'+(flight!.vesselName||'操縦機');$('#trackingControl').title=flight!.vesselName||'操縦機';}const children=allDebris(flight!),list=$('#debrisList');list.replaceChildren();($('#debrisCount') as {textContent:string|number}).textContent=children.length;for(const [index,f]of children.entries()){const row=document.createElement('div'),text=document.createElement('small'),button=document.createElement('button');text.textContent=(f.vesselName||'機体 '+(index+1))+' · '+f.parts.length+'部品 · '+((f.orbit?.altitude||0)/1000).toFixed(1)+' km · 軌道 '+(f.orbit?.speed??0).toFixed(0)+' m/s · 燃料 '+Math.round(f.fuelRatio*100)+'% · 電力 '+powerTotals(f.parts,f.charge).stored.toFixed(0)+' EC'+(f.crashed?' · 損傷':f.landed?' · 着地':'');button.textContent=trackedDebris===f?'追跡中':'追跡';button.onclick=()=>{trackedDebris=f;const target=vesselCenter(f);frameTrackedVessel(controls,target,bodyUp(target,flight!.universalTime));flightFocus.copy(target);updateDebrisList();};const take=document.createElement('button');take.textContent=canControl(f)?'操縦':'制御不可';take.disabled=!canControl(f);take.onclick=()=>switchVessel(f);const targetButton=document.createElement('button');targetButton.textContent=flight!.navigationTarget===f?'目標指定中':'目標にする';targetButton.onclick=()=>{setTarget(flight!,flight!,f);updateNavigation();updateDebrisList();};row.append(text,button,take,targetButton);list.append(row);}}
$('#trackPrimary').onclick=$('#returnCamera').onclick=()=>{trackedDebris=null;$('#trackingFocus').hidden=true;frame();};
function flightCenter(){return statistics(flight!.parts,flight!.fuel,flight!.ballast,flight!.thermal).com.applyQuaternion(flight!.q).add(flight!.pos);}
function frame(){setCameraUp(flight?bodyUp(flightCenter(),flight.universalTime):new T.Vector3(0,1,0));const bounds=new T.Box3();if(flight){craftRoot.updateWorldMatrix(true,true);for(const p of flight.parts){const object=objects.get(p.id);if(object)bounds.expandByObject(object);}}else bounds.setFromObject(craftRoot);if(bounds.isEmpty())return;if(!flight){const fit=workshopFrame(bounds,camera.fov,camera.aspect);controls.maxDistance=fit!.maxDistance;scene.fog=new T.Fog('#293c49',fit!.fogNear,fit!.fogFar);controls.target.copy(fit!.target);camera.position.copy(fit!.target).add(new T.Vector3(1,.65,1.3).normalize().multiplyScalar(fit!.distance));controls.update();return;}const fit=workshopFrame(bounds,camera.fov,camera.aspect);flightFocus.copy(flightCenter());controls.target.copy(fit!.target);camera.position.copy(fit!.target).add(flightFrameOffset(fit!.distance*(flight.environment==='water'?1:1.5),bodyUp(flightCenter(),flight.universalTime),flight.environment==='water'));controls.update();}
