let moonGlobe:T.Mesh,groundFacilities:T.Group,flightScenery:FlightScenery|undefined,planetMaterial:ReturnType<typeof surfaceMaterial>,patchMaterial:ReturnType<typeof surfaceMaterial>;function buildTestWorld(environment:string){disposeWorld();groundFacilities=new T.Group();testWorld.add(groundFacilities);const color=environment==='water'?'#164c64':'#627569';planetMaterial=surfaceMaterial(environment==='water');const globe=new T.Mesh(new T.SphereGeometry(PLANET.radius,256,128),planetMaterial);globe.layers.set(1);globe.position.copy(center);testWorld.add(globe);moonGlobe=new T.Mesh(new T.SphereGeometry(MOON.radius,192,96),mat('#92918d',0,1));moonGlobe.layers.set(1);moonGlobe.position.copy(bodyState(MOON,flight!.universalTime).position);testWorld.add(moonGlobe);const geometry=new T.PlaneGeometry(4000,4000,64,64);geometry.rotateX(-Math.PI/2);const positions=geometry.attributes.position;for(let i=0;i<positions.count;i++){const x=positions.getX(i),z=positions.getZ(i);positions.setY(i,Math.sqrt(PLANET.radius**2-x*x-z*z)-PLANET.radius+.01);}geometry.computeVertexNormals();patchMaterial=surfaceMaterial(environment==='water');surfacePatch=new T.Mesh(geometry,patchMaterial);flightScenery=new FlightScenery(testWorld);surfacePatch.receiveShadow=true;testWorld.add(surfacePatch);if(environment!=='water'){addLaunchpad(groundFacilities,assets.get('launchpad'));addSurveyMarkers(groundFacilities,assets);const runwaySite=new T.Group();runwaySite.quaternion.copy(launchSiteOrientation('runway'));runwaySite.position.set(0,PLANET.radius,0).applyQuaternion(runwaySite.quaternion);groundFacilities.add(runwaySite);const runwayGeometry=new T.PlaneGeometry(RUNWAY.width,RUNWAY.length,1,80);runwayGeometry.rotateX(-Math.PI/2);runwayGeometry.translate(0,0,RUNWAY.center);const rp=runwayGeometry.attributes.position;for(let i=0;i<rp.count;i++)rp.setY(i,.025-(rp.getX(i)**2+rp.getZ(i)**2)/(2*PLANET.radius));runwayGeometry.computeVertexNormals();const runway=new T.Mesh(runwayGeometry,mat('#3a4245'));runway.receiveShadow=true;runwaySite.add(runway);for(let z=-40;z<1400;z+=22)box(runwaySite,[.25,.01,8],[0,.035-z*z/(2*PLANET.radius),z],mat('#d8d7bd'));}}
$('#clearTarget').onclick=()=>{if(flight){setTarget(flight,flight,null);updateNavigation();updateDebrisList();}};
function updateNavigation(){resolveTargets(flight!);updateDocking();const relative=relativeState(flight!,flight!.navigationTarget);$('#targetInfo').textContent=relative?'目標まで '+relative.distance.toFixed(1)+' m · 相対速度 '+relative.speed.toFixed(2)+' m/s':'目標未指定';$('#targetDetail').textContent=relative?(relative.closing>=0?'接近 ':'離脱 ')+Math.abs(relative.closing).toFixed(2)+' m/s · '+(relative.braking?'減速方向まで '+(Math.acos(T.MathUtils.clamp(new T.Vector3(0,flight!.rocketAxes?1:0,flight!.rocketAxes?0:1).applyQuaternion(flight!.q).dot(relative.braking),-1,1))*180/Math.PI).toFixed(0)+'° · 整列後 I でRCS噴射':'速度差 0.01 m/s以下 · 噴射を停止'):'';if(relative&&flight!.portTranslationEnabled)$('#targetDetail').textContent='ポート基準の並進中 · 右のポート誘導で接近';$('#translationHelp').textContent=flight!.portTranslationEnabled?'RCS並進: I/K 接近・離脱 · J/L 左右 · U/O 上下（目標ポート基準）':'RCS並進: I/K 前後 · J/L 左右 · U/O 上下（機体軸）';$('#clearTarget').hidden=!relative;const nav=drawNavball($<HTMLCanvasElement>('#navball'),flight!.q,flight!.rocketAxes,flightCenter(),flight!.vel,flight!.universalTime,flight!.navigationFrame);$('#navPitch').textContent='HDG '+(nav.heading===null?'—':String(Math.round(nav.heading)%360).padStart(3,'0')+'°')+' · PITCH '+nav.pitch.toFixed(0)+'°';$('#sasMode').value=flight!.sasMode;updateSasDirections(flight!);}
