function catalog(){const q=$('#search').value.toLowerCase();$('#parts').innerHTML=Object.entries(PARTS).filter(([k,d])=>(category==='すべて'||category===d.cat)&&(`${d.name} ${d.code} ${k}`).toLowerCase().includes(q)).map(([k,d])=>`<button class="partcard" data-type="${k}" title="${d.desc}"><span class="partcode">${d.code}</span><em>+</em><img src="${assets.get(k)!.userData.thumbnail}" alt=""><strong>${d.name}</strong></button>`).join('');$$('.partcard').forEach(b=>b.onclick=()=>beginPlacement(b.dataset.type as PartType));}
