async function boot(){try{($('#catalogCount') as {textContent:string|number}).textContent=Object.keys(PARTS).length;const loader=new GLTFLoader();await Promise.all(Object.keys(PARTS).map(async type=>{const gltf=await loader.loadAsync(`./assets/parts/${PARTS[type].model||type}.glb`);assets.set(type,gltf.scene);assetBounds.set(type,new T.Box3().setFromObject(gltf.scene));}));const thumbRenderer=new T.WebGLRenderer({antialias:true,alpha:true,preserveDrawingBuffer:true});thumbRenderer.setSize(180,120);thumbRenderer.setPixelRatio(1);thumbRenderer.toneMapping=T.ACESFilmicToneMapping;thumbRenderer.toneMappingExposure=1.05;const ts=new T.Scene();ts.environment=scene.environment;ts.add(new T.HemisphereLight('#ffffff','#6e8998',1.2));const light=new T.DirectionalLight('#fff4db',2.5);light.position.set(4,6,5);ts.add(light);const tc=new T.PerspectiveCamera(33,1.5,.01,100);for(const [type,model]of assets){const clone=model.clone(true);ts.add(clone);const b=new T.Box3().setFromObject(clone),center=b.getCenter(new T.Vector3()),s=b.getSize(new T.Vector3()).length();tc.position.copy(center).add(new T.Vector3(1.3,.8,1.8).normalize().multiplyScalar(s*1.8));tc.lookAt(center);thumbRenderer.render(ts,tc);model.userData.thumbnail=thumbRenderer.domElement.toDataURL();ts.remove(clone);}thumbRenderer.dispose();const shroud=await loader.loadAsync('./assets/parts/engine-shroud.glb');assets.set('engine-shroud',shroud.scene);const canopy=await loader.loadAsync('./assets/parts/parachute-open.glb');canopy.scene.traverse((o:T.Object3D)=>{if((o as T.Mesh).isMesh)((o as T.Mesh).material as T.Material).side=T.DoubleSide;});assets.set('parachute-open',canopy.scene);await Promise.all(['north','east'].map(async id=>{const marker=await loader.loadAsync('./assets/scenery/survey-'+id+'.glb');assets.set('survey-'+id,marker.scene);}));const pad=await loader.loadAsync('./assets/scenery/launchpad.glb');assets.set('launchpad',pad.scene);catalog();restoreWorkspace();rebuild();frame();$('#loading').hidden=true;await initializeCenter();}catch(e){console.error(e);$('#loading').innerHTML='<strong>部品を読み込めませんでした</strong><span>ページを再読み込みしてください。</span>';}}
boot();

