 const ownId=portOptions($<HTMLSelectElement>('#ownPort'),own,flight!.dockingPorts?.own),targetId=portOptions($<HTMLSelectElement>('#targetPort'),other,flight!.dockingPorts?.target);selectDockingPorts(flight!,ownId&&targetId?ownId:null,ownId&&targetId?targetId:null);
 const guide=flight!.dockingPorts?portGuidance(flight!,ownId,target,targetId):null,status=guide?dockingStatus(flight!,ownId,target!,targetId):null;
