 if(dockingArmed&&(dockingArmed.flight!==flight||dockingArmed.own!==ownId||dockingArmed.target!==targetId))dockingArmed=null;const connect=()=>{dockingArmed=null;try{refreshDockedFlight(dockVessels(flight!,target!,ownId,targetId));gameAudio.play('dock');notify('ドッキング完了。1機として操縦できます。');}catch(e){notify((e as Error).message);}};$('#dockButton').disabled=!guide;$('#autoDock').disabled=!guide&&!dockingPilot.active;$('#autoDock').textContent=dockingPilot.active?'自動ドッキングを中止':'自動ドッキング';$('#autoDockStatus').textContent=dockingPilot.state==='idle'?'':'自動ドッキング：'+dockingPilot.message;$('#autoDock').onclick=()=>{if(dockingPilot.active){dockingPilot.stop('cancelled','中止しました');dockingArmed=null;return;}try{dockingPilot.start(flight);dockingArmed={flight,own:ownId,target:targetId};notify('自動ドッキング開始：整列→回り込み→待機点→最終接近の順に進みます。操縦キーで中止。');}catch(e){notify((e as Error).message);}};$('#dockButton').textContent=dockingArmed?'結合待機を解除':status?.ready?'目標と結合':'結合待機（接近は手動）';$('#dockButton').onclick=()=>{if(!guide)return;if(dockingArmed){dockingArmed=null;return;}if(status!.ready){connect();return;}dockingArmed={flight,own:ownId,target:targetId};notify('結合待機：条件がそろうと結合します。接近と減速は手動です。');};if(dockingArmed&&status?.ready)connect();
