function refreshCenter(){deliveryPanel.update();refreshHistory();$('#centerTime').textContent=formatUniversalTime(universalTime)+' · 共通時刻は停止中';let designCount=0,libraryError=false;try{designCount=loadDesigns().designs.length;}catch{libraryError=true;}const vesselCount=parkedWorld?(worldTrackingList)(parkedWorld).length:0,history=parkedWorld?.history??[];renderFirstSteps($('#centerFirstSteps'),{visible:!libraryError&&isFirstVisit({historyCount:history.length,vesselCount,designCount}),onStart:()=>enterWorkshop('vab')});const guide=$('#centerGuide');guide.replaceChildren();for(const item of centerGuidance({partCount:parts.length,designCount,vesselCount,libraryError,history})){const row=document.createElement('li'),title=document.createElement('b'),text=document.createElement('span');title.textContent=item.title;text.textContent=item.text;row.classList.toggle('completed',item.completed);row.append(title,text);guide.append(row);}const name=$('#craftName').value;$('#centerDraft').textContent=name+' · '+parts.length+'部品 · '+bayMode.toUpperCase();const active=parkedWorld?.vessels.find(v=>v.vesselId===parkedWorld!.activeVesselId)||parkedWorld?.vessels[0];$('#centerResume').disabled=!centerReady||!active;$('#centerFlightInfo').textContent=active?(active.vesselName||parkedWorld!.flightMeta?.name||'機体')+' · T+ '+active.state.time.toFixed(1)+'s · '+active.parts.length+'部品 · 保持 '+parkedWorld!.vessels.length+'機 · 一時停止中':'進行中の飛行はありません。';}
