function loadDesigns():import('./design-library.js').DesignLibrary{const raw=localStorage.getItem(DESIGN_LIBRARY_KEY);if(raw){if(raw.length>12000000)throw Error('設計一覧が大きすぎます');return readDesignLibrary(JSON.parse(raw));}const legacy=localStorage.getItem(storageKey('craft'));if(!legacy)return {version:1,designs:[]};const old=JSON.parse(legacy);return appendDesign({version:1,designs:[]},{name:typeof old.name==='string'?old.name:'以前の保存',parts:validateCraft(old),bay:'vab',environment:'land'},'legacy',0);}
