for(const [id,item]of Object.entries(CENTER_FACILITIES)){const button=$('#'+item.button);button.addEventListener('pointerenter',()=>centerView?.pointFacility(id));button.addEventListener('pointerleave',()=>centerView?.pointFacility(null));button.addEventListener('focus',()=>centerView?.focusFacility(id));button.addEventListener('blur',()=>centerView?.focusFacility(null));}
