function openTracking(focusId:string|null=null){try{const rows=worldTrackingList(parkedWorld,{includeOrbit:true});showModal('<div class="eyebrow">TRACKING STATION</div><h2>追跡施設</h2><p>機体を選んで操縦・観察を再開します。選択するまでは時間が停止しています。</p><div id="trackingMapHost"></div><div id="trackingRows"></div>');$('#modal').classList.add('trackingDialog');const list=$('#trackingRows'),map=mountTrackingMap($('#trackingMapHost'),rows as import('./tracking-map.js').TrackingMapRow<string|undefined>[],id=>{for(const row of list.querySelectorAll('article'))row.classList.toggle('selectedVessel',row.dataset.vessel===id);});appendRecoveryUndo(list);if(!rows.length){const empty=document.createElement('p');empty.textContent='進行中の飛行はありません。VAB/SPHで機体を作って出発してください。';list.append(empty);return;}for(const [index,item]of rows.entries()){const row=document.createElement('article');row.className='facilityRow'+(index===0?' selectedVessel':'');row.dataset.vessel=item.id as string;row.style.setProperty('--vessel-color',TRACKING_COLORS[index%TRACKING_COLORS.length]);const name=document.createElement('strong'),description=document.createElement('p');name.textContent=(index+1)+'. '+item.name;const select=document.createElement('button');select.textContent='軌道図で選択';select.onclick=()=>{map.select(item.id);for(const other of list.querySelectorAll('article'))other.classList.toggle('selectedVessel',other===row);};row.append(select);description.textContent=item.parts+'部品 · 高度 '+(item.altitude/1000).toFixed(2)+' km · 軌道 '+item.speed.toFixed(1)+' m/s · 地表 '+item.surfaceSpeed.toFixed(1)+' m/s · T+ '+item.time.toFixed(1)+'s · '+item.status;row.append(name,description);for(const burn of item.pendingBurns){const note=document.createElement('p');note.textContent=burn.label+' · UT '+burn.time.toFixed(1)+' s · '+(burn.overdue?'予定時刻を過ぎています。操縦を再開して再計画・削除を確認':'噴射まで '+formatDuration(burn.time-item.universalTime));row.append(note);}for(const [observe,label]of [[false,'操縦を再開'],[true,'観察を再開']] as [boolean,string][]){const button=document.createElement('button');button.textContent=label;button.disabled=!observe&&!item.controllable;button.onclick=()=>{try{const selection=selectWorldVessel(parkedWorld!,item.id!,{observe});$('#modal').close();resumeFromCenter(selection);}catch(e){$('#centerNotice').textContent=(e as Error).message;}};row.append(button);}const retire=document.createElement('button');retire.textContent=item.recovery.action;retire.onclick=()=>confirmRecovery(item);row.append(retire);list.append(row);if(item.id===focusId||item.anchorPartId===focusId){select.click();row.scrollIntoView({block:'center'});}}}catch(e){$('#centerNotice').textContent='追跡一覧を開けませんでした：'+(e as Error).message;}}
function openLaunchLibrary(facility:string){try{const library=loadDesigns();showModal('<div class="eyebrow">LAUNCH OPERATIONS</div><h2>'+ (facility==='workshop'?'保存した設計':facility==='pad'?'発射台':'滑走路')+'</h2><p>保存した設計の版を選びます。作業中の設計は保持されます。</p><button id="saveDraftToLibrary">作業中の設計を一覧に保存</button><div id="launchDesignRows"></div>');$('#saveDraftToLibrary').onclick=()=>{if(saveDesign())openLaunchLibrary(facility);else {const message=document.createElement('p');message.textContent='保存できませんでした。機体が空でないか、ブラウザの保存容量を確認してください。';$('#launchDesignRows').prepend(message);}};const list=$('#launchDesignRows');if(!library.designs.length){const empty=document.createElement('p');empty.textContent='まだ保存した設計がありません。上のボタンで現在の設計を保存できます。';list.append(empty);}for(const design of [...library.designs].reverse()){const row=document.createElement('article');row.className='facilityRow';const name=document.createElement('strong'),info=document.createElement('p'),button=document.createElement('button');name.textContent=design.name;info.textContent=design.parts.length+'部品 · '+design.bay.toUpperCase()+' · '+(design.savedAt?new Date(design.savedAt).toLocaleString():'以前の保存');button.textContent=facility==='workshop'?'設計を読み込む':facility==='pad'?'発射台から出発':'滑走路から出発';button.onclick=()=>{if(facility==='workshop'){if(flight)return;$('#modal').close();loadData({version:1,name:design.name,parts:design.parts});setBay(design.bay);$('#environment').value=design.environment;updateDepartureButton(document,design.environment);persistWorkspace();}else launchStoredDesign(library,design.id,facility);};row.append(name,info,button);list.append(row);}}catch(e){$('#centerNotice').textContent='設計一覧を開けませんでした：'+(e as Error).message;}}
