function finishPractice(){
 if(!practiceSession)return;
 const home=practiceSession.home;
 if(flight)endFlight();practiceSession=null;
 parkedWorld=home.world;universalTime=home.world.universalTime;
 parts=home.workshop.parts;$('#craftName').value=home.workshop.name;
 setBay(home.workshop.bay);$('#environment').value=home.workshop.environment;
 keys.clear();physicsClock.reset();rebuild();frame();updateInfo();
 notify('練習を終了しました。通常世界の機体・時刻・設計に戻りました。');
}
function launchAdditional(design:import('./practice-session.js').PracticeDesign&{bay?:string}){
 if(flight||practiceSession){notify('現在の飛行を終了してから出発してください');return;}
 let next:Flight|null=null,candidate:PracticeSession|null=null;
 const draft={parts,name:$('#craftName').value,environment:$('#environment').value,bay:bayMode};
 try{
  const home=gameRecord({world:parkedWorld??worldFromFlight(null,{universalTime}),draft});
  const practice=departureMode(design.environment).mode==='practice';
  if(practice){
   if(workspaceError)throw Error('通常世界の保存エラーを解消してから練習を開始してください');
   candidate=new PracticeSession(home,design);candidate.saveHome(localStorage);
  }
  const launchedWorld=candidate?candidate.initialWorld:launchWorld(home.world,design);
  next=loadFlight(flightFromWorld(launchedWorld)!);launchPartOrigins=new Map(next.parts.map((p,i)=>[p.id,design.parts[i]?.id]));
  practiceSession=candidate;$('#modal').close();enterWorkshop(design.bay||bayMode);
  parts=structuredClone(next.parts);$('#craftName').value=next.vesselName;
  $('#environment').value=next.environment;rebuild();startFlight(next);activeFlightName=next.vesselName;
  parkedWorld=launchedWorld;parts=draft.parts;$('#craftName').value=draft.name;
  $('#environment').value=draft.environment;bayMode=draft.bay;persistWorkspace();
  notify(practice?'独立した練習を開始しました。通常世界は停止・保持されています。':historyActionLabel(launchedWorld.history.at(-1)!)+' · 他の機体 '+(fleet(flight!).length-1)+'機を保持');
 }catch(e){
  if(practiceSession){if(next===flight)next=null;finishPractice();}
  if(next&&next!==flight)next.dispose();
  parts=draft.parts;$('#craftName').value=draft.name;$('#environment').value=draft.environment;bayMode=draft.bay;
  notify((e as Error).message);
  if((e as import('./launch-clearance.js').LaunchSiteError).code==='launch_site_occupied'){showModal('<h2>出発地点を使用中</h2><div id="launchBlockers"></div>');for(const item of (e as import('./launch-clearance.js').LaunchSiteError).blockers!){const row=document.createElement('article'),name=document.createElement('strong'),button=document.createElement('button');row.className='facilityRow';name.textContent=item.name;button.textContent='追跡施設で確認';button.onclick=()=>{showCenter();openTracking(item.id);};row.append(name,button);$('#launchBlockers').append(row);}return;}
  if($('#modal').open){const message=document.createElement('p');message.textContent=(e as Error).message;$('#modalBody').append(message);}
 }
}

function appendRecoveryUndo(list:HTMLElement){if(!recoveryUndo||JSON.stringify(parkedWorld)!==recoveryUndo.after)return;const text=document.createElement('p'),button=document.createElement('button');text.textContent=recoveryUndo.message+'。再開・追加出発・再読込するまでは取り消せます。';button.textContent='直前の回収・運用終了を取り消す';button.onclick=()=>{if(!recoveryUndo||JSON.stringify(parkedWorld)!==recoveryUndo.after)return;const after=parkedWorld;parkedWorld=structuredClone(recoveryUndo.before);if(!persistWorkspace()){parkedWorld=after;return;}recoveryUndo=null;refreshCenter();openTracking();};list.append(text,button);}
function confirmRecovery(item:import('./world-operations.js').WorldTrackingRow){showModal('<div class="eyebrow">MISSION OPERATIONS</div><h2 id="retireTitle"></h2><p id="retireSummary"></p><p>この機体だけを飛行一覧から外します。保存設計と他の機体は保持します。直後に取り消せますが、再開・追加出発・再読込後は取り消せません。</p><button id="confirmRetire">実行</button><button id="cancelRetire">戻る</button>');$('#retireTitle').textContent=item.recovery.action+'の確認';$('#retireSummary').textContent=item.name+' · '+item.parts+'部品 · '+item.recovery.reason;$('#cancelRetire').onclick=openTracking as ()=>void;$('#confirmRetire').onclick=()=>{try{const before=structuredClone(parkedWorld),result=retireWorldVessel(parkedWorld!,item.id!,item.recovery.recoverable?'recover':'terminate');parkedWorld=result.world;if(!persistWorkspace()){parkedWorld=before;throw Error('保存できなかったため機体を保持しました');}recoveryUndo={before:before!,after:JSON.stringify(parkedWorld),message:result.removed.name+'を'+result.removed.action+'しました'};refreshCenter();openTracking();}catch(e){$('#retireSummary').textContent=(e as Error).message;}};}

function branchGhost(branch:PartBranch){const group=new T.Group(),preview=placeBranch([],branch,{position:[0,0,0],rotation:[0,0,0]});for(const p of preview.parts){const model=cloneModel(p.type);model.position.fromArray(p.p);model.rotation.set(...p.r);group.add(model);}return group;}
function renderAssemblyTree(){const panel=$('#assemblyTree'),list=$('#assemblyTreeRows');panel.hidden=!!flight;const scroll=list.scrollTop;list.replaceChildren();if(flight)return;const branch=selected?descendants(parts,selected):new Set();for(const [index,item]of assemblyTree(parts).entries()){const row=document.createElement('li'),button=document.createElement('button');row.style.paddingLeft=Math.min(item.depth,12)*12+'px';button.textContent=(index+1)+'. '+PARTS[item.type].code+' '+PARTS[item.type].name+' · 枝'+item.count+' · 段'+item.stage;button.classList.toggle('branchMember',branch.has(item.id));button.setAttribute('aria-pressed',String(item.id===selected));button.onclick=()=>{cancelPlacement();select(item.id);};row.append(button);list.append(row);}list.scrollTop=scroll;($('#assemblyTreeCount') as {textContent:string|number}).textContent=parts.length;}

function clearInterferenceHighlight(){fuelOverlay.clear();$('#fuelNetwork')?.setAttribute('aria-pressed','false');for(const o of [...interferenceOverlay.children] as T.LineSegments<T.BufferGeometry,T.Material>[]){o.geometry.dispose();o.material.dispose();interferenceOverlay.remove(o);}for(const row of document.querySelectorAll('.interferencePairActive'))row.classList.remove('interferencePairActive');}
function showInterferencePair(pair:import('./assembly-interference.js').InterferencePair,focusId:string,row:HTMLElement){if(flight)return;cancelPlacement();select(focusId);for(const [index,id]of [pair.a,pair.b].entries()){const p=parts.find(p=>p.id===id);if(!p)continue;for(const box of partInterferenceBounds(p,assetBounds)){const shape=new T.BoxGeometry(...box.half.clone().multiplyScalar(2).toArray()),edges=new T.EdgesGeometry(shape);shape.dispose();const line=new T.LineSegments(edges,new T.LineBasicMaterial({color:index?'#55dce8':'#ff9c56',depthTest:false}));line.position.copy(box.center);line.quaternion.copy(box.quaternion);line.renderOrder=20;interferenceOverlay.add(line);}}row.classList.add('interferencePairActive');}
function renderInterferences(){const list=$('#interferenceRows');list.replaceChildren();if(flight)return;const result=assemblyInterferences(parts,assetBounds);($('#interferenceCount') as {textContent:string|number}).textContent=result.total;$('#interferenceSummary').textContent=result.total?(result.total+' 組。'+(result.total>result.pairs.length?'先頭 '+result.pairs.length+' 組を表示。':'')+'部品名を選ぶと橙・水色の箱で表示します。'):'箱同士の明確な重なりはありません。';const indices=new Map(parts.map((p,i)=>[p.id,i+1]));for(const pair of result.pairs){const row=document.createElement('article');row.className='interferencePair';for(const [index,id]of [pair.a,pair.b].entries()){const p=parts.find(p=>p.id===id)!,button=document.createElement('button');button.textContent=(index?'水色':'橙')+' '+indices.get(id)+'. '+PARTS[p.type].code+' '+PARTS[p.type].name;button.onclick=()=>showInterferencePair(pair,id,row);row.append(button);}list.append(row);}}

function updateWorkshop(){if(flight)return;const bounds=new T.Box3().setFromObject(craftRoot),layout=workshopLayout(bounds,camera.fov,camera.aspect);bay.position.fromArray(layout.origin);workshopFloor=layout.origin[1];room.scale.fromArray(layout.roomScale);workshopDeck.scale.set(layout.platformScale,1,layout.platformScale);workshopGround.scale.set((layout.gridSize+10)/90,1,(layout.gridSize+10)/90);if(workshopGridSize!==layout.gridSize){grid.removeFromParent();grid.geometry.dispose();for(const material of Array.isArray(grid.material)?grid.material:[grid.material])material.dispose();workshopGridSize=layout.gridSize;const step=Math.max(1,Math.ceil(workshopGridSize/200));grid=new T.GridHelper(workshopGridSize,Math.ceil(workshopGridSize/step),'#647984','#435963');grid.position.y=-.16;bay.add(grid);}const fit=workshopFrame(bounds,camera.fov,camera.aspect);if(fit){controls.maxDistance=fit.maxDistance;scene.fog=new T.Fog('#293c49',fit.fogNear,fit.fogFar);}}

